import {P} from './palette.js';
import {oval,line,shape,shadow,leaf,star} from './shapes.js';
import {blink,clamp} from './animation.js';

export function zombieFace(c,t,uid,hit=0){oval(c,0,-14,13,14,hit>.1?P.hit:P.skin);oval(c,-6,-10,5,6,P.skinShade,false);oval(c,-5,-17,4,4.2*blink(t,uid),P.cream);oval(c,5,-15,3.2,3.4*blink(t,uid),P.cream);oval(c,-4,-17,1.5,2,P.ink,false);oval(c,5,-14,1.2,1.6,P.ink,false);line(c,[[-5,-6],[1,-4],[7,-6]],P.ink,2);shape(c,[[0,-5],[0,-1],[3,-1],[3,-5]],P.cream);line(c,[[-9,-24],[-7,-30],[-4,-26]],P.ink,2)}
function death(c,o){if(!o.death)return;c.globalAlpha*=1-o.death;c.translate(o.death*12,o.death*8);c.rotate(o.death*1.3)}
function cone(c,t,ratio){c.save();c.translate(0,-25);c.rotate(Math.sin(t*2)*.045+(1-ratio)*.22);shape(c,[[-15,0],[-5,-25],[1,-29],[7,-15],[14,1]],P.fire);shape(c,[[-9,-11],[9,-10],[6,-17],[-6,-18]],P.cream);shape(c,[[-5,-25],[1,-29],[4,-21],[0,-23]],P.gold);oval(c,0,1,17,3,P.fire);if(ratio<.6)line(c,[[8,-5],[2,-9],[7,-12]],P.bark,1.5);c.restore()}
function bucket(c,t,ratio){c.save();c.translate(0,-24);c.rotate(Math.sin(t)*.025+(1-ratio)*-.16);shape(c,[[-15,-17],[13,-17],[16,2],[-15,2]],P.metal);oval(c,-1,-17,14,3,P.metalDark);line(c,[[-9,-12],[-8,-1]],P.cream,3);line(c,[[-15,-8],[-20,-5],[-17,9],[11,10],[19,-4],[14,-8]],P.metalDark,2);if(ratio<.7)line(c,[[8,-12],[3,-8],[9,-7]],P.metalDark,2);if(ratio<.35)line(c,[[-3,-3],[2,-6],[5,0]],P.metalDark,2);c.restore()}
function drawSprinter(c,z,x,y,t,o){const run=Math.sin(t*13),attack=o.attack||0;c.save();c.translate(x,y);shadow(c,0,23,14);death(c,o);c.rotate(-.22-(o.hit||0)*.15);for(const side of [-1,1]){const phase=run*side;line(c,[[side*4,6],[side*(9+phase*5),17],[side*(4-phase*6),27]],P.clothDark,6);oval(c,side*(5-phase*6),28,7,3,P.shoe)}shape(c,[[-8,-9],[8,-10],[10,8],[-7,10]],P.cloth);line(c,[[-6,-5],[-18-attack*4,1+run*4],[-23,7+run*5]],P.skinShade,5);line(c,[[7,-6],[18+attack*5,-1-run*4],[23,5-run*5]],P.skinShade,5);c.save();c.translate(2,-12);c.rotate(.16);zombieFace(c,t,z.uid,o.hit);c.restore();for(let i=0;i<2;i++){c.globalAlpha=.2;line(c,[[-28-i*7,9+i*8],[-14,9+i*8]],P.cream,2)}eliteOverlay(c,z,t);c.restore()}
function drawBrute(c,z,x,y,t,o){const walk=Math.sin(t*3.2),attack=o.attack||0;c.save();c.translate(x,y);shadow(c,0,27,25);death(c,o);for(const side of [-1,1]){line(c,[[side*11,9],[side*(12+walk*2),27]],P.clothDark,12);oval(c,side*(14+walk*2),30,10,5,P.shoe)}shape(c,[[-23,-17],[20,-19],[24,13],[-21,14]],P.skinShade);shape(c,[[-21,-14],[-4,-19],[0,13],[-22,12]],P.wood);shape(c,[[2,-18],[19,-17],[22,6],[6,10]],P.metalDark);for(const side of [-1,1])line(c,[[side*19,-10],[side*(29-attack*7),4],[side*(28-attack*9),19-attack*11]],P.skinShade,15);c.save();c.translate(0,-24);zombieFace(c,t,z.uid,o.hit);shape(c,[[-15,-24],[-5,-31],[15,-25],[12,-20]],P.bark);c.restore();if(o.hit>.1||z.flash>.05){c.globalAlpha=.75;for(let i=0;i<3;i++)line(c,[[18+i*2,-11+i*7],[27+i*2,-8+i*7]],P.metal,2)}eliteOverlay(c,z,t);c.restore()}
function drawSporekeeper(c,z,x,y,t,o){const walk=Math.sin(t*4.5),pulse=(z.castPulse||0)>0?1+Math.sin(t*18)*.12:1;c.save();c.translate(x,y);shadow(c,0,23,15);death(c,o);c.rotate(.13);for(const side of [-1,1])line(c,[[side*6,7],[side*(8+walk*2),24]],P.clothDark,6);shape(c,[[-11,-10],[10,-13],[13,10],[-9,12]],P.dark);oval(c,-9,-12,10,16,P.bark);for(let i=0;i<4;i++){const a=i*1.7+t*.25;oval(c,-9+Math.cos(a)*8,-15+Math.sin(a)*8,4,3,i%2?P.light:P.green)}for(const side of [-1,1])line(c,[[side*8,-4],[side*16,9],[side*18,20]],P.skinShade,5);c.save();c.translate(2,-17);zombieFace(c,t,z.uid,o.hit);c.restore();if((z.castPulse||0)>0){c.globalAlpha=.3;c.strokeStyle=P.heal;c.lineWidth=3;c.beginPath();c.ellipse(0,0,30*pulse,18*pulse,0,0,Math.PI*2);c.stroke();for(let i=0;i<4;i++)leaf(c,Math.cos(t*4+i*1.57)*25,Math.sin(t*4+i*1.57)*15,4,t+i,P.heal)}eliteOverlay(c,z,t);c.restore()}
function drawVolatile(c,z,x,y,t,o){const ratio=clamp(z.hp/z.maxHp),pulse=1+Math.sin(t*(ratio<.3?14:6))*(ratio<.3?.11:.045),walk=Math.sin(t*5);c.save();c.translate(x,y);shadow(c,0,23,17);death(c,o);for(const side of [-1,1])line(c,[[side*7,8],[side*(8+walk*2),24]],P.clothDark,7);c.save();c.scale(pulse,pulse);oval(c,0,-2,16,20,P.green);shape(c,[[-12,-12],[-4,-18],[8,-16],[14,-5],[10,12],[-10,12]],P.leaf);for(let i=0;i<5;i++){const a=i*2.2;line(c,[[Math.cos(a)*5,Math.sin(a)*7-2],[Math.cos(a)*12,Math.sin(a)*15-2]],i%2?P.fire:P.sun,2)}c.restore();for(const side of [-1,1])line(c,[[side*12,-5],[side*18,11]],P.skinShade,5);c.save();c.translate(0,-22);zombieFace(c,t,z.uid,o.hit);c.restore();c.globalAlpha=.28+.18*Math.sin(t*8);oval(c,0,-2,22,25,ratio<.3?P.fire:P.light,false);c.globalAlpha=1;eliteOverlay(c,z,t);c.restore()}
function eliteOverlay(c,z,t){if(!z.elite)return;if(z.elite==='hasty')for(let i=0;i<2;i++){c.globalAlpha=.3;line(c,[[-29-i*5,4+i*9],[-16,4+i*9]],P.cream,2)}if(z.elite==='armored'){shape(c,[[-14,-10],[-4,-14],[0,-3],[-12,1]],P.metal);shape(c,[[5,-11],[14,-8],[13,3],[3,-2]],P.metalDark)}if(z.elite==='regenerating')for(let i=0;i<3;i++)leaf(c,Math.cos(t*2+i*2.1)*18,-10+Math.sin(t*2+i*2.1)*12,4,t+i,P.heal);if(z.elite==='frenzied'){oval(c,-5,-17,2,2,P.fire,false);oval(c,5,-15,2,2,P.fire,false)}if(z.elite==='toxic'){c.globalAlpha=.28;for(let i=0;i<3;i++)oval(c,Math.sin(t*2+i)*15,10-i*9,5,4,P.green,false)}}
export function drawZombie(c,z,x,y,time,o={}){const t=time+(z.uid||0)*1.31;if(z.id==='sprinter')return drawSprinter(c,z,x,y,t,o);if(z.id==='brute')return drawBrute(c,z,x,y,t,o);if(z.id==='sporekeeper')return drawSporekeeper(c,z,x,y,t,o);if(z.id==='volatile')return drawVolatile(c,z,x,y,t,o);const walk=o.moving===false?0:Math.sin(t*6),attack=o.attack||0,ratio=clamp(z.hp/z.maxHp);c.save();c.translate(x,y);shadow(c,0,22,16);death(c,o);c.rotate(Math.sin(t*3)*.045+(o.hit||0)*-.2);for(const side of [-1,1]){c.save();c.translate(side*6,8);c.rotate(side*walk*.2);line(c,[[0,0],[side*2,9],[side*2,15]],P.clothDark,7);oval(c,side*2+2,16,6,3.5,P.shoe);c.restore()}c.save();c.translate(0,-Math.abs(walk)*1.5);shape(c,[[-10,-6],[9,-8],[13,8],[6,12],[-10,10],[-13,1]],P.cloth);shape(c,[[-4,-5],[2,-6],[5,9],[-2,10]],P.clothDark);line(c,[[-8,2],[-4,3]],P.cream,1);for(const side of [-1,1]){c.save();c.translate(side*10,-2);c.rotate(side*(.1+walk*.1)-attack*.9);line(c,[[0,0],[side*3,7],[side*2+attack*8,12-attack*13]],P.clothDark,6);oval(c,side*2+attack*8,12-attack*13,4.5,5,P.skin);c.restore()}c.save();c.translate(Math.sin(t*3+.5)*1.4,-attack*2);c.rotate(-attack*.12);zombieFace(c,t,z.uid,o.hit);if(z.id==='conehead')cone(c,t,ratio);if(z.id==='buckethead')bucket(c,t,ratio);c.restore();c.restore();eliteOverlay(c,z,t);c.restore()}

export function drawEliteBadge(c,z,x,y,time){if(!z.elite)return;c.save();c.translate(x,y-34);c.globalAlpha=.92;const colors={hasty:P.cream,armored:P.metal,regenerating:P.heal,frenzied:P.fire,toxic:P.green};star(c,0,0,5,colors[z.elite]||P.sun,time*.5);c.restore()}
